format_data:
{
 "header": {
  "columns": [
   {
    "label": "",
    "fields": [
     {
      "label": "Spacer",
      "fieldname": "spacer_nCtaGVsw",
      "fieldtype": "Spacer",
      "custom": 1,
      "height": 20
     }
    ]
   }
  ],
  "gap": 0
 },
 "sections": [
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Text",
       "fieldname": "static_text_title",
       "fieldtype": "Static Text",
       "custom": 1,
       "text": "LETTER OF APPOINTMENT",
       "align": "center",
       "bold": 1,
       "font_size": 20,
       "custom_style": "letter-spacing:0.12em;margin-bottom:18px;"
      },
      {
       "label": "Divider",
       "fieldname": "divider_title_rule",
       "fieldtype": "Divider",
       "custom": 1,
       "custom_style": "margin:10px 0 14px;border-bottom:2px solid #1f272e;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Custom HTML",
       "fieldname": "custom_html_reference",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- macro date(v) -%}{{ frappe.utils.global_date_format(v, format=\"medium\") }}{%- endmacro -%}\n<table style=\"width:100%;\"><tr><td>Ref: {{ doc.name }}</td><td style=\"text-align:right;\">{{ frappe.utils.global_date_format(doc.letter_date or doc.creation, format='long') }}</td></tr></table>\n<p style=\"margin-top:16px;\">To,<br><b>{{ doc.applicant_name }}</b>{% if doc.employee %}<br>Employee ID: {{ doc.employee }}{% endif %}{% for line in (doc.address or \"\").splitlines() %}<br>{{ line|e }}{% endfor %}</p>\n",
       "custom_style": ""
      },
      {
       "label": "Subject",
       "fieldname": "custom_html_subject",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\nSubject: Letter of Appointment{% if offer.designation %} - {{ offer.designation }}{% endif %}\n",
       "custom_style": "margin:20px 0px 20px 0px;\ntext-align:justify;\nfont-weight:700;"
      },
      {
       "label": "Greeting",
       "fieldname": "custom_html_greeting",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- macro date(v) -%}{{ frappe.utils.global_date_format(v, format=\"medium\") }}{%- endmacro -%}\n<p>Dear {{ doc.applicant_name }},</p>\n{%- if doc.introduction %}\n<p>{{ doc.introduction }}</p>\n{%- else %}\n<p>With reference to your acceptance of our offer{% if offer.offer_date %} dated {{ date(offer.offer_date) }}{% endif %}, we are pleased to appoint you{% if offer.designation %} as <b>{{ offer.designation }}</b>{% endif %} with {{ doc.company }} on the terms and conditions set out below.</p>\n{%- endif %}\n<p>Please treat this letter as a legal document. By accepting this appointment, you agree to be bound by the terms and conditions set out in it.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_appointment_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{{ 1 }}. Appointment and Reporting",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Appointment and Reporting",
       "fieldname": "custom_html_appointment",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- macro date(v) -%}{{ frappe.utils.global_date_format(v, format=\"medium\") }}{%- endmacro -%}\n{%- set department = frappe.db.get_value(\"Department\", offer.department, \"department_name\") if offer.department else None -%}\n{%- set manager = frappe.db.get_value(\"Employee\", offer.reports_to, \"employee_name\") if offer.reports_to else None -%}\n<p>Your appointment takes effect from {{ date(doc.appointment_date) }}. You will be employed{% if offer.designation %} as {{ offer.designation }}{% endif %}{% if department %} in the {{ department }} department{% endif %}.{% if manager %} You will report to {{ manager }}, or to any other person the Company names from time to time.{% endif %}{% if offer.employment_type %} Your employment will be on a {{ offer.employment_type|lower }} basis.{% endif %}{% if offer.grade %} You will be placed in grade {{ offer.grade }}.{% endif %}{% if doc.employee %} Your employee ID is {{ doc.employee }}.{% endif %}</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_duties_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "2. Duties and Responsibilities",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Duties",
       "fieldname": "custom_html_duties",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{{ doc.job_responsibilities }}\n<p>You will also carry out any other duties that the Company assigns to you from time to time, in line with your role.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ],
   "visible_if": "doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip()"
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_remuneration_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 2 + d }}. Remuneration",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Remuneration",
       "fieldname": "custom_html_remuneration",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=offer.currency) }}{%- endmacro -%}\n{%- if offer.ctc %}\n<p>Your total cost to company will be <b>{{ money(offer.ctc) }}</b> per annum. The break-up of your remuneration is set out in Annexure A.</p>\n{%- if offer.variable %}\n<p>This includes a variable component of {{ money(offer.variable) }} per annum, payable subject to your performance and that of the Company.</p>\n{%- endif %}\n{%- else %}\n<p>Your remuneration will be as set out in your offer letter.</p>\n{%- endif %}\n<p>Your remuneration is subject to the deductions that the law requires, including income tax and contributions to statutory schemes. You will be covered by statutory benefits such as provident fund, employees' state insurance and gratuity, where they apply to you. Your remuneration is personal to you and you must keep it confidential.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_probation_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 3 + d }}. Probation and Confirmation",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Probation and Confirmation",
       "fieldname": "custom_html_probation",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- if offer.probation_period_days %}\n<p>You will be on probation for {{ offer.probation_period_days }} days from your date of joining. The Company may extend the probation period. Your employment is confirmed only when the Company issues you a letter of confirmation in writing.</p>\n{%- if offer.notice_period_during_probation %}\n<p>During probation, either party may end the employment by giving {{ offer.notice_period_during_probation }} days' written notice, or salary in lieu of notice.</p>\n{%- else %}\n<p>During probation, either party may end the employment without notice.</p>\n{%- endif %}\n{%- elif offer %}\n<p>Your appointment is not subject to a probation period.</p>\n{%- else %}\n<p>Your probation and confirmation will be governed by the Company's policies.</p>\n{%- endif %}\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_time_off_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 4 + d }}. Working Hours, Leave and Holidays",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Working Hours, Leave and Holidays",
       "fieldname": "custom_html_time_off",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- macro num(v) -%}{{ v|int if v == v|int else v }}{%- endmacro -%}\n{%- if (doc.start_time and doc.end_time) or offer.working_hours or offer.weekly_off_days or offer.total_public_holidays %}\n<p>{% if doc.start_time and doc.end_time %}Your work hours will be {{ frappe.utils.format_time(doc.start_time, \"h:mm a\") }} to {{ frappe.utils.format_time(doc.end_time, \"h:mm a\") }}.{% endif %}{% if offer.working_hours %} Your normal working day will be {{ num(offer.working_hours) }} hours.{% endif %}{% if offer.weekly_off_days %} Your weekly off will fall on {{ \" and \".join(offer.weekly_off_days.rsplit(\", \", 1)) }}.{% endif %}{% if offer.total_public_holidays %} You will be entitled to {{ offer.total_public_holidays }} public holidays in each calendar year.{% endif %}</p>\n{%- endif %}\n{%- if offer.leave_allocations %}\n<p>You will be entitled to {% for row in offer.leave_allocations %}{{ num(row.annual_allocation) }} days of {{ row.leave_type }}{% if loop.revindex == 2 %} and {% elif not loop.last %}, {% endif %}{% endfor %} per annum, in line with the Company's leave policy. Leave in your first year is calculated on a pro-rata basis from your date of joining.</p>\n{%- else %}\n<p>You will be entitled to leave in line with the Company's leave policy for your position and location.</p>\n{%- endif %}\n<p>You may be required to work beyond normal hours when the work requires it, in line with applicable law.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_reimbursement_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 5 + d }}. Reimbursement of Expenses",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Reimbursement of Expenses",
       "fieldname": "custom_html_reimbursement",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>The Company will reimburse expenses that you incur on its behalf in carrying out your duties, such as travel for assigned work and business telephone calls, when you submit proof of the expense and in line with the Company's policies.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_transfer_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 6 + d }}. Place of Work",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Place of Work",
       "fieldname": "custom_html_transfer",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n<p>Your initial place of posting will be {{ offer.branch or \"as communicated to you by the Company\" }}. You may be required to travel for work as your duties require.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_termination_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 7 + d }}. Notice Period and Termination",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Notice Period and Termination",
       "fieldname": "custom_html_termination",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set offer = frappe.get_cached_doc(\"Job Offer\", doc.job_offer) if doc.job_offer else {} -%}\n{%- if offer.notice_number_of_days %}\n<p>After confirmation, either party may end this employment by giving {{ offer.notice_number_of_days }} days' written notice, or salary in lieu of the notice period. The Company may decide whether to accept salary in lieu of notice from you.</p>\n{%- else %}\n<p>After confirmation, the notice period will be governed by the Company's policies.</p>\n{%- endif %}\n<p>If you resign, the Company may relieve you before the end of the notice period, without salary for the remaining days.</p>\n<p>The Company may end your employment immediately, without notice or salary in lieu of notice, if you:</p>\n<ul>\n<li>disclose any information about the Company or its business to a person outside the Company, except in the ordinary course of business;</li>\n<li>are found guilty of dishonesty or moral turpitude in dealing with the Company's money, material or documents;</li>\n<li>are found to have given incorrect information, or to have concealed information, in your resume or joining documents; or</li>\n<li>do not comply with the Company's policies and guidelines, as amended from time to time.</li>\n</ul>\n<p>When you resign or your employment ends, you will be relieved only after you complete the handover of your duties, assignments and projects. You must return all Company property, documents and data in your possession. Any dues that you owe the Company will be adjusted against the amount payable to you in your full and final settlement.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_confidentiality_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 8 + d }}. Confidentiality and Intellectual Property",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Confidentiality and Intellectual Property",
       "fieldname": "custom_html_confidentiality",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>You must not disclose any confidential information of the Company, its clients or its partners, during or after your employment, except when your duties or the law require it.</p>\n<p>All work, inventions and intellectual property that you create in the course of your employment belong to the Company.</p>\n<p>During your employment, you must not take up any other employment or business without the Company's prior written consent.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_policies_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 9 + d }}. Company Policies and Conduct",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Company Policies and Conduct",
       "fieldname": "custom_html_policies",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>You will be bound by the Company's rules, policies and code of conduct, as amended from time to time, including its policies on information security and the prevention of harassment at the workplace.</p>\n<p>This appointment is subject to the verification of your credentials, references and background. You must tell the Company in writing about any change in your address or personal details.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_retirement_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 10 + d }}. Retirement",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Retirement",
       "fieldname": "custom_html_retirement",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- if doc.retirement_age %}\n<p>You will retire from the service of the Company on reaching the age of {{ doc.retirement_age }} years.</p>\n{%- else %}\n<p>Your age of retirement will be as per the Company's policies.</p>\n{%- endif %}\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_law_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 11 + d }}. Governing Law",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Governing Law",
       "fieldname": "custom_html_law",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>This appointment is governed by the laws of the country in which you are employed.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_terms_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set d = 1 if doc.job_responsibilities and doc.job_responsibilities.replace('<div class=\"ql-editor read-mode\">', '').replace('</div>', '').replace('<p><br></p>', '').strip() else 0 -%}\n{{ 12 + d }}. Additional Terms",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Additional Terms",
       "fieldname": "custom_html_terms",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- for term in doc.terms %}\n<p>{% if term.title %}<b>{{ term.title }}</b><br>{% endif %}{{ (term.description or \"\")|replace(\"\\n\", \"<br>\") }}</p>\n{%- endfor %}\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ],
   "visible_if": "doc.terms"
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Heading",
       "fieldname": "custom_html_acceptance_title",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "Acceptance",
       "custom_style": "font-size:15px;font-weight:700;margin:10px 0px;"
      },
      {
       "label": "Acceptance",
       "fieldname": "custom_html_acceptance",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>Please sign and return the duplicate copy of this letter as a token of your acceptance of these terms.</p>\n<p>We welcome you to {{ doc.company }} and wish you a rewarding career with us.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ],
   "keep_together": 1
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Spacer",
       "fieldname": "spacer_classic_sign",
       "fieldtype": "Spacer",
       "custom": 1,
       "height": 30
      },
      {
       "label": "Custom HTML",
       "fieldname": "custom_html_classic_for",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>For {{ doc.company }},</p>\n",
       "custom_style": "text-align:justify;"
      },
      {
       "label": "Signature",
       "fieldname": "signature",
       "fieldtype": "Attach Image",
       "show_label": "hide",
       "width": "69px"
      },
      {
       "label": "Custom HTML",
       "fieldname": "custom_html_classic_signoff",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "{%- set signatory = frappe.db.get_value(\"Employee\", {\"user_id\": doc.owner}, \"employee_name\") or frappe.get_fullname(doc.owner) -%}\n<p>{{ signatory }}<br>{{ doc.company }}</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
   ]
  },
  {
   "label": "",
   "columns": [
    {
     "label": "",
     "fields": [
      {
       "label": "Divider",
       "fieldname": "divider_accept_rule",
       "fieldtype": "Divider",
       "custom": 1,
       "custom_style": "margin:18px 0 12px;border-bottom-color:#d5dae0;"
      },
      {
       "label": "Text",
       "fieldname": "static_text_accept",
       "fieldtype": "Static Text",
       "custom": 1,
       "text": "Declaration of Acceptance",
       "bold": 1,
       "custom_style": "margin:10px 0px;"
      },
      {
       "label": "Custom HTML",
       "fieldname": "custom_html_declaration",
       "fieldtype": "HTML",
       "custom": 1,
       "html": "<p>I, {{ doc.applicant_name }}, have read and understood the terms and conditions of this letter of appointment, and I agree to be bound by them.</p>\n",
       "custom_style": "text-align:justify;"
      }
     ]
    }
